    lemma_perm_tuples(db, db2, params);
    lemma_perm_having(db, db2, params);
        assert(bag_eq(tuples(db, params), tuples(db2, params)));
        let keep1 = |t: Tuple| having(db, params, t.s_.sic, t.t_.tlabel, t.p.stmt);
        let keep2 = |t: Tuple| having(db2, params, t.s_.sic, t.t_.tlabel, t.p.stmt);
